import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); fz = repo / 'target/debug/fz'

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run([str(fz), 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return root, payload

def messages(payload):
    return [item['message'] for item in payload['items']]

json_helpers_root, json_helpers = verify('json_helpers', '''
    fn load() -> JsonHandle {
        return json.parse("{\"items\":{\"a\":\"1\",\"b\":\"2\"}}")
    }
    fn item_keys(payload: JsonHandle) -> ListHandle {
        return json.keys(payload)
    }
    fn main() -> i32 {
        let payload = load()
        let keys = item_keys(payload)
        return list.len(keys)
    }
''', 0)
assert json_helpers['errors'] == 0, json_helpers
assert not any('resource escape' in message or 'was not consumed/freed' in message or 'uses moved value' in message for message in messages(json_helpers)), json_helpers

list_helpers_root, list_helpers = verify('list_helpers', '''
    fn size(items: ListHandle) -> i32 {
        return list.len(items)
    }
    fn main() -> i32 {
        let items = list.new()
        discard list.push(items, "alpha")
        discard list.push(items, "beta")
        return size(items) + list.len(items)
    }
''', 0)
assert list_helpers['errors'] == 0, list_helpers
assert not any('resource escape' in message or 'was not consumed/freed' in message or 'uses moved value' in message for message in messages(list_helpers)), list_helpers

map_helpers_root, map_helpers = verify('map_helpers', '''
    fn build_map() -> MapHandle {
        let payload = map.new()
        discard map.set(payload, "a", "1")
        discard map.set(payload, "b", "2")
        return payload
    }
    fn count(payload: MapHandle) -> i32 {
        return map.len(payload)
    }
    fn main() -> i32 {
        let payload = build_map()
        discard map.set(payload, "c", "3")
        return count(payload) + map.len(payload)
    }
''', 0)
assert map_helpers['errors'] == 0, map_helpers
assert not any('resource escape' in message or 'was not consumed/freed' in message or 'uses moved value' in message for message in messages(map_helpers)), map_helpers

artifact_root, artifact_payload = verify('collection_artifacts', '''
    fn main() -> i32 {
        let payload = json.parse("{\"items\":{\"a\":\"1\",\"b\":\"2\"}}")
        let items = json.keys(payload)
        let table = json.to_map(json.path(payload, "items"))
        discard list.len(items)
        discard map.len(table)
        return 0
    }
''', 0)
assert artifact_payload['errors'] == 0, artifact_payload
memory_report = json.loads((artifact_root / '.fz' / 'memory-report.json').read_text())
contracts = json.loads((artifact_root / '.fz' / 'native-runtime-contracts.json').read_text())
assert 'JsonHandle' in json.dumps(memory_report), memory_report
assert 'ListHandle' in json.dumps(memory_report), memory_report
assert 'MapHandle' in json.dumps(memory_report), memory_report
contracts_text = json.dumps(contracts)
assert 'json.parse' in contracts_text and 'produces_handle' in contracts_text, contracts
assert 'json.to_map' in contracts_text and 'observes_handle' in contracts_text, contracts
assert 'json.keys' in contracts_text and 'produces_handle' in contracts_text, contracts
assert 'list.len' in contracts_text and 'observes_handle' in contracts_text, contracts
assert 'map.len' in contracts_text and 'observes_handle' in contracts_text, contracts

print('compiler-memory-collection-handles-ok')

